package cn.binbin.crm;
import java.util.*;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
public record P3Access(BusinessAccess.Scope tickets,boolean slaManage,boolean knowledgeRead,boolean knowledgeWrite,boolean knowledgePublish,BusinessAccess.Scope campaigns,boolean campaignLaunch,boolean integrationRead,boolean integrationManage,boolean export) {
 public static final List<String> FIELDS=List.of("ticket","sla","knowledge","campaign","integration");
 private static BusinessAccess.Scope scope(List<Map<String,Object>> ps,String module){boolean r=false,w=false,ra=false,rd=false,wa=false,wd=false;for(var p:ps){boolean cr=Boolean.TRUE.equals(p.get(module+"_can_read")),cw=cr&&Boolean.TRUE.equals(p.get(module+"_can_write"));String s=(String)p.get("record_scope");r|=cr;w|=cw;ra|=cr&&"ALL".equals(s);rd|=cr&&"DEPARTMENT".equals(s);wa|=cw&&"ALL".equals(s);wd|=cw&&"DEPARTMENT".equals(s);}return new BusinessAccess.Scope(r,w,ra,rd,wa,wd);}
 private static boolean flag(List<Map<String,Object>> ps,String key,String role){return ps.stream().anyMatch(p->(role==null||role.equals(p.get("role_code")))&&Boolean.TRUE.equals(p.get(key)));}
 public static P3Access from(List<Map<String,Object>> p){var tickets=scope(p,"ticket");var campaigns=scope(p,"campaign");boolean kr=flag(p,"knowledge_can_read",null),kw=kr&&flag(p,"knowledge_can_write",null),ir=flag(p,"integration_can_read",null);return new P3Access(tickets,tickets.read()&&flag(p,"sla_can_manage","SALES_MANAGER"),kr,kw,kw&&flag(p,"knowledge_can_publish","SALES_MANAGER"),campaigns,campaigns.write()&&flag(p,"campaign_can_launch","SALES_MANAGER"),ir,ir&&flag(p,"integration_can_manage","TENANT_ADMIN"),flag(p,"p3_can_export",null));}
 public static P3Access none(){return from(List.of());}
 public static P3Access defaults(Set<String> roles){return from(roles.stream().map(role->{boolean mgr=role.equals("SALES_MANAGER"),sales=role.equals("SALES"),admin=role.equals("TENANT_ADMIN"),read=mgr||sales||role.equals("VIEWER"),write=mgr||sales;return SaasService.parameters("role_code",role,"record_scope",mgr||role.equals("VIEWER")?"ALL":"OWN_SHARED","ticket_can_read",read,"ticket_can_write",write,"sla_can_manage",mgr,"knowledge_can_read",read,"knowledge_can_write",write,"knowledge_can_publish",mgr,"campaign_can_read",read,"campaign_can_write",write,"campaign_can_launch",mgr,"integration_can_read",admin,"integration_can_manage",admin,"p3_can_export",mgr);}).toList());}
 public static void initialize(NamedParameterJdbcTemplate db,UUID tenant){db.update("UPDATE sys_role_policy SET ticket_can_read=role_code IN('SALES_MANAGER','SALES','VIEWER'),ticket_can_write=role_code IN('SALES_MANAGER','SALES'),sla_can_manage=role_code='SALES_MANAGER',knowledge_can_read=role_code IN('SALES_MANAGER','SALES','VIEWER'),knowledge_can_write=role_code IN('SALES_MANAGER','SALES'),knowledge_can_publish=role_code='SALES_MANAGER',campaign_can_read=role_code IN('SALES_MANAGER','SALES','VIEWER'),campaign_can_write=role_code IN('SALES_MANAGER','SALES'),campaign_can_launch=role_code='SALES_MANAGER',integration_can_read=role_code='TENANT_ADMIN',integration_can_manage=role_code='TENANT_ADMIN',p3_can_export=role_code='SALES_MANAGER' WHERE tenant_id=:tenant",Map.of("tenant",tenant));}
 public static void policy(NamedParameterJdbcTemplate db,UUID tenant,String role,Map<String,Object> old,SaasService.PolicyInput i){String[] cols={"ticket_can_read","ticket_can_write","sla_can_manage","knowledge_can_read","knowledge_can_write","knowledge_can_publish","campaign_can_read","campaign_can_write","campaign_can_launch","integration_can_read","integration_can_manage","p3_can_export"};Boolean[] input={i.ticketCanRead(),i.ticketCanWrite(),i.slaCanManage(),i.knowledgeCanRead(),i.knowledgeCanWrite(),i.knowledgeCanPublish(),i.campaignCanRead(),i.campaignCanWrite(),i.campaignCanLaunch(),i.integrationCanRead(),i.integrationCanManage(),i.p3CanExport()};var p=SaasService.parameters("tenant",tenant,"role",role);boolean[] values=new boolean[cols.length];for(int n=0;n<cols.length;n++){values[n]=input[n]==null?Boolean.TRUE.equals(old.get(cols[n])):input[n];p.put("p"+n,values[n]);}
  if(values[1]&&!values[0]||values[2]&&(!values[0]||!role.equals("SALES_MANAGER"))||values[4]&&!values[3]||values[5]&&(!values[4]||!role.equals("SALES_MANAGER"))||values[7]&&!values[6]||values[8]&&(!values[7]||!role.equals("SALES_MANAGER"))||values[10]&&(!values[9]||!role.equals("TENANT_ADMIN"))||role.equals("VIEWER")&&(values[1]||values[2]||values[4]||values[5]||values[7]||values[8]||values[10]||values[11]))throw ApiError.bad("P3 权限需先授予读取；发布、执行与 SLA 限经理，集成管理限企业管理员，只读成员不可写入或导出");
  var set=new ArrayList<String>();for(int n=0;n<cols.length;n++)set.add(cols[n]+"=:p"+n);db.update("UPDATE sys_role_policy SET "+String.join(",",set)+" WHERE tenant_id=:tenant AND role_code=:role",p);
 }
}
